-- Fix 74e (G4) after 73e + 73e2: EQUIPMENT is back in the CLD. Resume the guarded DT under control
-- and refresh it now. Drift must be empty first (the guard would suspend it again otherwise).
alter dynamic table {{DEMO_DB}}.L2.DT_EQUIPMENT_DOWNTIME resume;
alter dynamic table {{DEMO_DB}}.L2.DT_EQUIPMENT_DOWNTIME refresh;

insert into {{DEMO_DB}}.CONTROL.SCHEMA_CHANGE_LOG (SCENARIO, EVENT, GUARDRAIL, DETAIL, SOURCE)
values ('74e', 'RESUMED', 'G4', 'EQUIPMENT republished; guarded DT resumed and refreshed', 'PRESENTER');
